function SmallMeteor(){
         var Obj={};
         Obj.init=function(x,y,direction,life,lifeforpixel)
         {
          this.x=x;
          this.y=y;
          this.direction=direction;
          this.life=life;
          this.lifeforpixel=lifeforpixel;
          };
          Obj.Update=function()
        {
           this.x+=Math.cos(this.direction);
           this.y+=Math.sin(this.direction);
           this.life--;
           if(this.lifeforpixel>0.02)
           this.lifeforpixel-=0.006;
         };
   Obj.GetAngle=function(x,y)
{
         var dx, dy;
	 var distance;
         var cosa = 0;
	 dx = this.x - x;
	 dy = this.y - y;
	 distance = Math.sqrt(dx*dx + dy*dy);
		 if ((dx <= 0) && (dy > 0))
		 {
			 cosa = Math.abs(dy / distance);
			 this.direction = Math.acos(cosa);
		 }
		 if ((dx < 0) && (dy <= 0))
		 {
			 cosa = Math.abs(dx / distance);
			  this.direction = Math.acos(cosa) + 1.57;
		 }
		 if ((dx >= 0) && (dy<0))
		 {
			 cosa = Math.abs(dy / distance);
			  this.direction = Math.acos(cosa) + 3.14;
		 }
		 if ((dx>0) && (dy >= 0))
		 {
			 cosa = Math.abs(dx / distance);
			 this.direction  = Math.acos(cosa) - 1.57;
		 }
                 this.direction-=1.57;
};
       return Obj;
}

